[Authorize(AuthenticationSchemes="Identity.Application,CallMedClinical",Roles = "Paciente,Psicologo,Medico,Funcionario,Admin"),ResponseCache(NoStore=true,Location=ResponseCacheLocation.None),RequestSizeLimit(180000)]
public sealed class JornadaController(MKSANContext db,JornadaService jornada,AgendamentoService agenda,EncaixeService encaixe,IClinicaClock clock):Controller {
 string Uid=>User.FindFirstValue(ClaimTypes.NameIdentifier)!;
 Task<Consulta?> Minha(int id,CancellationToken ct)=>jornada.Visiveis(User).SingleOrDefaultAsync(x=>x.Id==id,ct);
 public IActionResult Index()=>View();
 public async Task<IActionResult> Dados(CancellationToken ct,DateTime? data=null){if(!ModelState.IsValid)return BadRequest();var dia=(data??clock.Hoje).Date;if(dia==DateTime.MaxValue.Date)return BadRequest();var consultaBase=jornada.Visiveis(User).AsNoTracking();consultaBase=JornadaService.Equipe(User)?consultaBase.Where(c=>c.Data>=dia&&c.Data<dia.AddDays(1)):consultaBase.Where(c=>c.Data>=clock.Hoje.AddDays(-7)&&c.Data<=clock.Hoje.AddDays(90));var cs=await consultaBase.OrderBy(c=>c.Data).ThenBy(c=>c.Horario).Take(200).ToListAsync(ct);var ids=cs.Select(c=>c.Id).ToArray();var js=await db.Jornadas.AsNoTracking().Include(x=>x.Sala).Where(x=>ids.Contains(x.ConsultaId)).ToDictionaryAsync(x=>x.ConsultaId,ct);var equipe=JornadaService.Equipe(User);var pid=User.HasClaim(x=>x.Type=="clinical.consulta")?0:await db.Pacientes.Where(p=>p.UsuarioId==Uid&&p.Ativo).Select(p=>p.Id).FirstOrDefaultAsync(ct);
  return Json(new{equipe=JornadaService.Equipe(User),consultas=cs.Select(c=>new{c.Id,data=c.Data.ToString("yyyy-MM-dd"),c.Horario,c.Status,medico=c.Medico?.Nome,paciente=JornadaService.Equipe(User)||JornadaService.Medico(User,c)?c.Paciente?.Nome:null,online=js.GetValueOrDefault(c.Id)?.Tele==true,encerrada=JornadaService.Encerrada(c),etapa=JornadaService.Encerrada(c)?c.Status:JornadaService.Etapa(js.GetValueOrDefault(c.Id))}),ofertas=await db.Ofertas.AsNoTracking().Where(o=>(equipe||o.ListaEspera.PacienteId==pid)&&o.ListaEspera.Ativa&&o.Estado=="Aberta"&&o.ExpiraEm>DateTime.UtcNow).Take(100).Select(o=>new{o.Id,o.Data,o.Horario,o.ExpiraEm,paciente=equipe?o.ListaEspera.Paciente!.Nome:null}).ToListAsync(ct)});
 }
 public async Task<IActionResult> Consulta(int id,CancellationToken ct){var c=await Minha(id,ct);if(c==null)return NotFound();ViewBag.J=await jornada.ObterAsync(id,ct);ViewBag.Menor=c.Paciente!=null&&PsicologiaService.Menor(c.Paciente,clock.Hoje);ViewBag.Autorizacoes=JornadaService.Medico(User,c)?await db.AutorizacoesResponsaveis.Where(x=>x.PacienteId==c.PacienteId&&x.PsicologoId==c.MedicoId).OrderByDescending(x=>x.VerificadaEm).Take(10).ToListAsync(ct):new List<AutorizacaoResponsavel>();ViewBag.P=JornadaService.Paciente(User,c);ViewBag.M=JornadaService.Medico(User,c);ViewBag.E=JornadaService.Equipe(User);ViewBag.Salas=await db.Salas.AsNoTracking().Where(x=>x.Ativa).OrderBy(x=>x.Nome).ToListAsync(ct);return View(c);}
 [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> Mover(int id,string acao,bool confirmar,CancellationToken ct){var c=await Minha(id,ct);if(c==null)return NotFound();var error=await jornada.MoverAsync(c,User,acao,confirmar,ct);TempData[error==null?"Sucesso":"Erro"]=error??"Etapa atualizada.";return RedirectToAction(nameof(Consulta),new{id});}
 [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> Alocar(int id,int? salaId,int duracao,bool tele,CancellationToken ct){var c=await Minha(id,ct);if(c==null)return NotFound();var error=await jornada.AlocarAsync(c,User,salaId,duracao,tele,ct);TempData[error==null?"Sucesso":"Erro"]=error??"Organização atualizada.";return RedirectToAction(nameof(Consulta),new{id});}
 public async Task<IActionResult> Salas(CancellationToken ct){if(!JornadaService.Equipe(User))return Forbid();return Json(await db.Salas.AsNoTracking().OrderBy(x=>x.Nome).ToListAsync(ct));}
 [HttpPost,ValidateAntiForgeryToken]public async Task<IActionResult> Sala(int? id,string nome,bool ativa,CancellationToken ct){if(!JornadaService.Equipe(User))return Forbid();var atual=id.HasValue?await db.Salas.AsNoTracking().SingleOrDefaultAsync(x=>x.Id==id,ct):null;var erro=await HttpContext.RequestServices.GetRequiredService<SalasService>().SalvarAsync(id,nome,atual?.Localizacao,atual?.Recursos,ativa,User,ct);TempData[erro==null?"Sucesso":"Erro"]=erro??"Sala salva.";return RedirectToAction("Index","Salas");}
 [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> Oferta(Guid id,bool aceitar,CancellationToken ct){if(User.HasClaim(x=>x.Type=="clinical.consulta"))return Forbid();var o=await db.Ofertas.Include(x=>x.ListaEspera).SingleOrDefaultAsync(x=>x.Id==id&&x.ListaEspera.Paciente!.UsuarioId==Uid,ct);if(o==null)return NotFound();if(o.Estado!="Aberta"||o.ExpiraEm<=DateTime.UtcNow){TempData["Erro"]="A oferta expirou.";return RedirectToAction(nameof(Index));}if(!aceitar){var ok=await encaixe.RecusarAsync(id,o.ListaEspera.PacienteId,ct);TempData[ok?"Sucesso":"Erro"]=ok?"Oferta recusada. Você continua na lista.":"A oferta já mudou.";}else{var r=await agenda.AgendarAsync(o.ListaEspera.PacienteId,o.MedicoId,o.Data,o.Horario,"Encaixe aceito pelo paciente",ct:ct,ofertaId:id);TempData[r.Sucesso?"Sucesso":"Erro"]=r.Mensagem;if(r.Sucesso){jornada.Audit(User,"Aceitar vaga",r.Consulta!.Id);await db.SaveChangesAsync(ct);}}return RedirectToAction(nameof(Index));}
 [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> Prioridade(int id,int prioridade,CancellationToken ct){if(!JornadaService.Equipe(User))return Forbid();if(prioridade<0||prioridade>10)return BadRequest();var i=await db.ListasEspera.FindAsync([id],ct);if(i==null)return NotFound();i.Prioridade=prioridade;jornada.Audit(User,"Alterar prioridade de espera",id);await db.SaveChangesAsync(ct);return RedirectToAction("Index","ListaEspera");}
 public async Task<IActionResult> Indicadores(CancellationToken ct){if(!JornadaService.Equipe(User))return Forbid();return Json(await jornada.IndicadoresAsync(ct));}
 [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> Medicao(DateTime data,string periodo,int consultas,int faltas,int minutosRecepcao,string fonte,CancellationToken ct){if(!JornadaService.Equipe(User))return Forbid();if(data.Date>clock.Hoje||periodo is not ("Antes" or "Piloto")||consultas<1||faltas<0||faltas>consultas||minutosRecepcao<0||minutosRecepcao>14400||string.IsNullOrWhiteSpace(fonte)||fonte.Length>300)return BadRequest();db.MedicoesOperacionais.Add(new(){Data=data.Date,Periodo=periodo,Consultas=consultas,Faltas=faltas,MinutosRecepcao=minutosRecepcao,Fonte=fonte});jornada.Audit(User,"Medição operacional",0);await db.SaveChangesAsync(ct);return RedirectToAction(nameof(Index));}
 public async Task<IActionResult> Clinico(int id,CancellationToken ct){var c=await Minha(id,ct);if(c==null)return NotFound();if(!JornadaService.Paciente(User,c)&&!JornadaService.Medico(User,c))return StatusCode(403);jornada.Audit(User,"Abrir preparação clínica",id);await db.SaveChangesAsync(ct);var f=await db.FormulariosClinicos.AsNoTracking().Where(x=>x.MedicoId==c.MedicoId).OrderByDescending(x=>x.Id).FirstOrDefaultAsync(ct);var r=await db.RespostasClinicas.AsNoTracking().Where(x=>x.ConsultaId==id&&x.PacienteId==c.PacienteId&&x.MedicoId==c.MedicoId).OrderByDescending(x=>x.CriadoEm).FirstOrDefaultAsync(ct);if(r!=null)f=await db.FormulariosClinicos.AsNoTracking().SingleAsync(x=>x.Id==r.FormularioId,ct);var impedimento=await new PsicologiaService(db,clock).ImpedimentoAsync(c,ct);var up=c.Paciente?.UsuarioId;var um=c.Medico?.UsuarioId;return Json(new{impedimento,custodiantes=JornadaService.Medico(User,c)?await db.ChavesClinicas.AsNoTracking().Where(k=>k.RevogadaEm==null&&db.Psicologos.Any(p=>p.UsuarioId==k.UsuarioId&&p.UsuarioId!=um&&p.Ativo&&p.ResponsavelTecnico&&(p.AreaProfissional==""||p.AreaProfissional=="Psicologia")&&p.Crp!=null&&p.RegistroVerificadoEm!=null)).Select(k=>new{k.Id,k.UsuarioId,k.Publica,k.Impressao,nome=db.Psicologos.Where(p=>p.UsuarioId==k.UsuarioId).Select(p=>p.Nome).FirstOrDefault()}).ToListAsync(ct):null,usuarioId=Uid,pacienteId=up,medicoId=um,editar=impedimento==null&&JornadaService.Paciente(User,c)&&!JornadaService.Encerrada(c)&&!await db.Jornadas.AnyAsync(x=>x.ConsultaId==id&&x.InicioEm!=null,ct),formulario=f,resposta=r?.Envelope,revogadas=await db.ChavesClinicas.AsNoTracking().Where(x=>x.UsuarioId==Uid&&x.RevogadaEm!=null).Select(x=>x.Id).ToListAsync(ct),chaves=await db.ChavesClinicas.AsNoTracking().Where(x=>(x.UsuarioId==up||x.UsuarioId==um)&&x.RevogadaEm==null).Select(x=>new{x.Id,x.UsuarioId,x.Publica,x.Impressao}).ToListAsync(ct)});}
 [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> Chave([FromBody]ChaveInput input,CancellationToken ct){if(input==null||string.IsNullOrEmpty(input.Publica)||input.Publica.Length>3000)return BadRequest();if(!await db.Pacientes.AnyAsync(x=>x.UsuarioId==Uid&&x.Ativo,ct)&&!await db.Medicos.AnyAsync(x=>x.UsuarioId==Uid&&x.Ativo,ct))return Forbid();try{using var doc=JsonDocument.Parse(input.Publica);var p=doc.RootElement;if(p.EnumerateObject().Any(x=>x.Name is not ("kty" or "n" or "e" or "alg" or "ext" or "key_ops"))||p.GetProperty("kty").GetString()!="RSA"||p.GetProperty("e").GetString()!="AQAB")return BadRequest();if(p.TryGetProperty("alg",out var alg)&&alg.GetString()!="RSA-OAEP-256")return BadRequest();if(p.TryGetProperty("key_ops",out var ops)&&(ops.ValueKind!=JsonValueKind.Array||ops.GetArrayLength()!=1||ops[0].GetString()!="wrapKey"))return BadRequest();var n=p.GetProperty("n").GetString()!;var modulus=Microsoft.AspNetCore.WebUtilities.WebEncoders.Base64UrlDecode(n);if(modulus.Length!=384)return BadRequest();using var rsa=RSA.Create();rsa.ImportParameters(new(){Modulus=modulus,Exponent=[1,0,1]});var hash=Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(n+":AQAB"))).ToLowerInvariant();var k=await db.ChavesClinicas.SingleOrDefaultAsync(x=>x.UsuarioId==Uid&&x.Impressao==hash,ct);if(k==null){if(await db.ChavesClinicas.CountAsync(x=>x.UsuarioId==Uid&&x.RevogadaEm==null,ct)>=8)return BadRequest(new{mensagem="Restaure uma chave existente neste dispositivo."});k=new(){UsuarioId=Uid,Publica=input.Publica,Impressao=hash};db.ChavesClinicas.Add(k);await db.SaveChangesAsync(ct);}return Json(new{k.Id,k.Impressao,revogada=k.RevogadaEm!=null});}catch(Exception e)when(e is JsonException or KeyNotFoundException or FormatException or CryptographicException or InvalidOperationException){return BadRequest();}}
 [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> RevogarChave(Guid id,CancellationToken ct){var key=await db.ChavesClinicas.SingleOrDefaultAsync(x=>x.Id==id&&x.UsuarioId==Uid,ct);if(key==null)return NotFound();key.RevogadaEm??=DateTime.UtcNow;jornada.Audit(User,"Revogar chave clínica",0);await db.SaveChangesAsync(ct);return Json(new{mensagem="Chave revogada para novas respostas. As respostas anteriores permanecem cifradas para as chaves usadas na época."});}
 [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> Formulario(int id,string titulo,string perguntas,CancellationToken ct){var c=await Minha(id,ct);if(c==null)return NotFound();if(!JornadaService.Medico(User,c)||c.Medico?.HabilitadoClinicamente!=true)return Forbid();var qs=(perguntas??"").Split('\n',StringSplitOptions.RemoveEmptyEntries|StringSplitOptions.TrimEntries);if(qs.Length is <1 or >20||qs.Any(x=>x.Length>250)||string.IsNullOrWhiteSpace(titulo)||titulo.Length>120)return BadRequest();var v=await db.FormulariosClinicos.Where(x=>x.MedicoId==c.MedicoId).MaxAsync(x=>(int?)x.Versao,ct)??0;db.FormulariosClinicos.Add(new(){MedicoId=c.MedicoId,Titulo=titulo,Versao=v+1,Perguntas=JsonSerializer.Serialize(qs)});jornada.Audit(User,"Publicar perguntas",id);await db.SaveChangesAsync(ct);return RedirectToAction(nameof(Consulta),new{id});}
 [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> Resposta(int id,[FromBody]RespostaInput input,CancellationToken ct){if(input==null||!input.Consentiu||string.IsNullOrEmpty(input.Envelope)||input.Envelope.Length>150000)return BadRequest();await using var tx=db.Database.IsRelational()?await db.Database.BeginTransactionAsync(ct):null;await jornada.LockAsync("jornada:"+id,ct);var c=await Minha(id,ct);if(c==null)return NotFound();if(!JornadaService.Paciente(User,c)||JornadaService.Encerrada(c)||await db.Jornadas.AnyAsync(x=>x.ConsultaId==id&&x.InicioEm!=null,ct))return StatusCode(403);var bloqueio=await new PsicologiaService(db,clock).ImpedimentoAsync(c,ct);if(bloqueio!=null)return BadRequest(new{mensagem=bloqueio});if(!await db.FormulariosClinicos.AnyAsync(x=>x.Id==input.FormularioId&&x.MedicoId==c.MedicoId,ct))return BadRequest();try{using var doc=JsonDocument.Parse(input.Envelope);var e=doc.RootElement;var props=e.EnumerateObject().ToArray();if(props.Length!=4||props.Select(x=>x.Name).Distinct().Count()!=4||props.Any(x=>x.Name is not ("versao" or "iv" or "ciphertext" or "destinatarios")))return BadRequest();if(e.GetProperty("versao").GetInt32()!=1||Convert.FromBase64String(e.GetProperty("iv").GetString()!).Length!=12||Convert.FromBase64String(e.GetProperty("ciphertext").GetString()!).Length is <16 or >65536)return BadRequest();var rs=e.GetProperty("destinatarios").EnumerateArray().ToArray();if(rs.Length is <2 or >16)return BadRequest();if(rs.Any(x=>x.EnumerateObject().Count()!=2||x.EnumerateObject().Any(p=>p.Name is not ("id" or "key"))))return BadRequest();var ids=rs.Select(x=>x.GetProperty("id").GetGuid()).ToArray();if(ids.Distinct().Count()!=ids.Length||rs.Any(x=>Convert.FromBase64String(x.GetProperty("key").GetString()!).Length!=384))return BadRequest();var keys=await db.ChavesClinicas.Where(x=>ids.Contains(x.Id)&&x.RevogadaEm==null&&(x.UsuarioId==c.Paciente!.UsuarioId||x.UsuarioId==c.Medico!.UsuarioId)).ToListAsync(ct);if(keys.Count!=ids.Length||!keys.Any(x=>x.UsuarioId==c.Paciente!.UsuarioId)||!keys.Any(x=>x.UsuarioId==c.Medico!.UsuarioId))return BadRequest(new{mensagem="Paciente e psicólogo precisam configurar suas chaves."});db.RespostasClinicas.Add(new(){ConsultaId=id,FormularioId=input.FormularioId,MedicoId=c.MedicoId,PacienteId=c.PacienteId,Envelope=input.Envelope});jornada.Audit(User,"Salvar preparação criptografada",id);await db.SaveChangesAsync(ct);if(tx!=null)await tx.CommitAsync(ct);return Json(new{mensagem="Preparação enviada."});}catch(Exception e)when(e is JsonException or KeyNotFoundException or FormatException or InvalidOperationException){return BadRequest();}}
 public async Task<IActionResult> Registros(int id,CancellationToken ct){var c=await Minha(id,ct);if(c==null)return NotFound();var m=JornadaService.Medico(User,c);if(!m&&!JornadaService.Paciente(User,c))return Forbid();if(c.Medico?.EhPsicologia!=true)return Json(new{podePublicar=false,registros=Array.Empty<object>(),mensagem="Este atendimento utiliza o prontuário da sua especialidade."});jornada.Audit(User,"Consultar registros psicológicos",id);await db.SaveChangesAsync(ct);return Json(new{podePublicar=m&&c.Medico!.HabilitadoPsicologia,c.PacienteId,psicologoId=c.MedicoId,fhirIdentifierSystem=HttpContext.RequestServices?.GetService<IConfiguration>()?["PepIntegration:Fhir:IdentifierSystem"],psicologo=c.Medico?.Nome,crp=c.Medico?.Crp,paciente=c.Paciente?.Nome,registros=await db.RegistrosPsicologicos.AsNoTracking().Where(x=>x.ConsultaId==id&&x.PacienteId==c.PacienteId&&x.PsicologoId==c.MedicoId&&(m||x.Escopo=="Prontuario")).OrderBy(x=>x.CriadoEm).ToListAsync(ct)});}
 [HttpPost,ValidateAntiForgeryToken]
 public async Task<IActionResult> Registro(int id,[FromBody]RegistroInput input,CancellationToken ct){
  if(input==null||input.Id==Guid.Empty||input.Escopo is not ("Prontuario" or "Reservado")||input.Categoria is not ("Demanda" or "Objetivos" or "Evolucao" or "Encaminhamento" or "Encerramento"))return BadRequest();
  await using var tx=db.Database.IsRelational()?await db.Database.BeginTransactionAsync(ct):null;await jornada.LockAsync("registro:"+id,ct);
  var c=await Minha(id,ct);if(c==null)return NotFound();if(!JornadaService.Medico(User,c)||c.Medico?.HabilitadoPsicologia!=true)return Forbid();
  var existente=await db.RegistrosPsicologicos.AsNoTracking().SingleOrDefaultAsync(x=>x.Id==input.Id,ct);if(existente!=null)return existente.AutorUsuarioId==Uid&&existente.Envelope==input.Envelope?Json(new{id=input.Id,mensagem="Registro já publicado."}):Conflict();
  if(input.RetificaId.HasValue){var anterior=await db.RegistrosPsicologicos.AsNoTracking().SingleOrDefaultAsync(x=>x.Id==input.RetificaId&&x.ConsultaId==id&&x.PacienteId==c.PacienteId&&x.PsicologoId==c.MedicoId&&x.Escopo==input.Escopo,ct);if(anterior==null||await db.RegistrosPsicologicos.AnyAsync(x=>x.RetificaId==input.RetificaId,ct))return Conflict(new{mensagem="Selecione o último registro da sequência para retificar."});}
  var psicologia=HttpContext.RequestServices.GetRequiredService<PsicologiaService>();
  if(!await psicologia.EnvelopeValidoAsync(input.Envelope,c.Medico.UsuarioId!,c.Paciente?.UsuarioId,input.Escopo=="Reservado",ct))return BadRequest(new{mensagem="Configure as chaves dos destinatários. Registros reservados só podem incluir o psicólogo responsável."});
  db.RegistrosPsicologicos.Add(new(){Id=input.Id,ConsultaId=id,PacienteId=c.PacienteId,PsicologoId=c.MedicoId,AutorUsuarioId=Uid,Escopo=input.Escopo,Categoria=input.Categoria,RetificaId=input.RetificaId,Envelope=input.Envelope,Hash=PsicologiaService.Hash(input.Envelope)});
  jornada.Audit(User,"Publicar registro psicológico cifrado",id);await db.SaveChangesAsync(ct);if(tx!=null)await tx.CommitAsync(ct);return Json(new{id=input.Id,mensagem="Registro publicado. Correções devem ser feitas por retificação."});
 }
 [HttpPost,ValidateAntiForgeryToken]
 public async Task<IActionResult> Guarda(int id,[FromBody]GuardaInput input,CancellationToken ct){var c=await Minha(id,ct);if(c==null||!JornadaService.Medico(User,c)||c.Medico?.HabilitadoPsicologia!=true)return Forbid();if(input?.Registros==null||input.Registros.Length is <1 or >200||input.Registros.Select(x=>x.Id).Distinct().Count()!=input.Registros.Length)return BadRequest();var chave=await db.ChavesClinicas.AsNoTracking().SingleOrDefaultAsync(k=>k.Id==input.ChaveId&&k.RevogadaEm==null,ct);if(chave==null)return BadRequest();var rt=await db.Psicologos.AsNoTracking().SingleOrDefaultAsync(p=>p.UsuarioId==chave.UsuarioId&&p.Ativo&&p.ResponsavelTecnico&&(p.AreaProfissional==""||p.AreaProfissional=="Psicologia")&&p.Crp!=null&&p.RegistroVerificadoEm!=null,ct);if(rt==null||rt.Id==c.MedicoId)return BadRequest();await using var tx=db.Database.IsRelational()?await db.Database.BeginTransactionAsync(ct):null;await jornada.LockAsync("guarda:"+id,ct);foreach(var item in input.Registros){if(!await db.RegistrosPsicologicos.AnyAsync(x=>x.Id==item.Id&&x.ConsultaId==id&&x.PacienteId==c.PacienteId&&x.PsicologoId==c.MedicoId,ct))return NotFound();try{if(Convert.FromBase64String(item.Key).Length!=384)return BadRequest();}catch(Exception ex)when(ex is FormatException or ArgumentException){return BadRequest();}if(!await db.GuardasRegistrosPsicologicos.AnyAsync(x=>x.RegistroId==item.Id&&x.ChaveId==chave.Id,ct))db.GuardasRegistrosPsicologicos.Add(new(){RegistroId=item.Id,ChaveId=chave.Id,PsicologoId=rt.Id,ChaveCifrada=item.Key,ConcedidaPor=Uid});}jornada.Audit(User,"Compartilhar guarda cifrada com responsável técnico",id);await db.SaveChangesAsync(ct);if(tx!=null)await tx.CommitAsync(ct);return Json(new{mensagem="Chaves do acervo compartilhadas com o responsável técnico. Valide a leitura com ele antes do desligamento."});}
 public sealed record GuardaItem(Guid Id,string Key);
 public sealed record GuardaInput(Guid ChaveId,GuardaItem[] Registros);
 [HttpPost,ValidateAntiForgeryToken]
 public async Task<IActionResult> CopiaProntuario(int id,CancellationToken ct){var c=await Minha(id,ct);if(c==null||(!JornadaService.Paciente(User,c)&&!JornadaService.Medico(User,c)))return Forbid();jornada.Audit(User,"Solicitar cópia sigilosa de prontuário no próprio dispositivo",id);await db.SaveChangesAsync(ct);return Json(new{mensagem="Disponibilização registrada. A entrega formal a terceiros deve ser documentada pelo psicólogo."});}
 [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> Intercambio(int id,[FromBody]IntercambioInput input,CancellationToken ct){
  var c=await Minha(id,ct);if(c==null)return NotFound();
  if(input==null||input.Tipo is not ("Exportar" or "PrepararImportacao")||input.Hash==null||input.Hash.Length!=64||input.Hash.Any(ch=>!Uri.IsHexDigit(ch)))return BadRequest();
  if(input.Tipo=="PrepararImportacao"?(!JornadaService.Medico(User,c)||c.Medico?.HabilitadoPsicologia!=true):(!JornadaService.Paciente(User,c)&&!JornadaService.Medico(User,c)))return Forbid();
  jornada.Audit(User,input.Tipo+" documento FHIR no dispositivo SHA256 "+input.Hash.ToLowerInvariant(),id);await db.SaveChangesAsync(ct);return Json(new{ok=true});
 }
 public sealed record IntercambioInput(string Tipo,string Hash);
 public sealed record RegistroInput(Guid Id,string Escopo,string Categoria,string Envelope,Guid? RetificaId);
 public sealed record ChaveInput(string Publica);
 public sealed record RespostaInput(int FormularioId,string Envelope,bool Consentiu);
}
